package africa.growtogether.platform.ecs;
import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param;
public interface ConfigurationValueRepository extends JpaRepository<ConfigurationValue,UUID>{
 @Query("select v from ConfigurationValue v where v.definition.id=:definitionId and v.active=true and ((v.scope=africa.growtogether.platform.ecs.ConfigurationScope.TENANT and v.tenantId=:tenantId) or (v.scope=africa.growtogether.platform.ecs.ConfigurationScope.ORGANIZATION and v.organizationId=:organizationId) or (v.scope=africa.growtogether.platform.ecs.ConfigurationScope.COUNTRY and v.countryCode=:countryCode) or v.scope=africa.growtogether.platform.ecs.ConfigurationScope.PLATFORM)") List<ConfigurationValue> candidates(@Param("definitionId")UUID definitionId,@Param("tenantId")UUID tenantId,@Param("organizationId")UUID organizationId,@Param("countryCode")String countryCode);
 @Query("select v from ConfigurationValue v where v.definition.id=:definitionId and v.scope=:scope and ((:countryCode is null and v.countryCode is null) or v.countryCode=:countryCode) and ((:organizationId is null and v.organizationId is null) or v.organizationId=:organizationId) and ((:tenantId is null and v.tenantId is null) or v.tenantId=:tenantId)")
 Optional<ConfigurationValue> findExact(@Param("definitionId")UUID definitionId,@Param("scope")ConfigurationScope scope,@Param("countryCode")String countryCode,@Param("organizationId")UUID organizationId,@Param("tenantId")UUID tenantId);
}
